public class LongestPalindrome {
    // ========== 方法 1：中心扩展（面试首选） ==========
    public String longestPalindrome(String s) {
        if (s == null || s.length() < 2) return s;
        int start = 0, maxLen = 1;
        for (int i = 0; i < s.length(); i++) {
            // 奇数长度：以 s[i] 为中心
            int len1 = expand(s, i, i);
            // 偶数长度：以 s[i] 和 s[i+1] 之间为中心
            int len2 = expand(s, i, i + 1);
            int len = Math.max(len1, len2);
            if (len > maxLen) {
                maxLen = len;
                start = i - (len - 1) / 2; // 关键：由中心反推起始位置
            }
        }
        return s.substring(start, start + maxLen);
    }

    private int expand(String s, int left, int right) {
        while (left >= 0 && right < s.length()
               && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }
        // 退出时 left 和 right 各多走了一步，长度 = right - left - 1
        return right - left - 1;
    }

    // ========== 方法 2：动态规划 ==========
    public String longestPalindromeDP(String s) {
        int n = s.length();
        if (n < 2) return s;
        boolean[][] dp = new boolean[n][n];
        int start = 0, maxLen = 1;

        // 单字符都是回文
        for (int i = 0; i < n; i++) dp[i][i] = true;

        // 先枚举长度（保证 dp[i+1][j-1] 已计算）
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                if (s.charAt(i) != s.charAt(j)) continue;
                // 长度 ≤ 3 时，去掉首尾后最多一个字符，一定是回文
                if (len <= 3 || dp[i + 1][j - 1]) {
                    dp[i][j] = true;
                    if (len > maxLen) {
                        maxLen = len;
                        start = i;
                    }
                }
            }
        }
        return s.substring(start, start + maxLen);
    }

    public static void main(String[] args) {
        LongestPalindrome sol = new LongestPalindrome();
        System.out.println(sol.longestPalindrome("babad"));  // bab
        System.out.println(sol.longestPalindrome("cbbd"));   // bb
        System.out.println(sol.longestPalindrome("a"));      // a
        System.out.println(sol.longestPalindrome("ac"));     // a
        System.out.println(sol.longestPalindromeDP("babad")); // bab
        System.out.println(sol.longestPalindromeDP("cbbd"));  // bb
    }
}
